{"command":"kubectl get deploy app -n default -o json | python3 -c '
import sys, json; d=json.load(sys.stdin.read()); s=d["status"];t=d.get("spec","{}");
print("generation=" + str(s["generation"]) + " observed=" + str(s["observedGeneration"]) + "\n");
print("available=" + str(s["availableReplicas"]) + " ready=" + str(s["readyReplicas"]) + " updated=" + str(s["updatedReplicas"]) + " replicas=" + str(s["replicas"]) + "\n")
print("progressivelyUpdatingReplicas=" + str(s["progressivelyUpdatingReplicas"]))
if "progressivelyUpdatingReplicas" not in s:
    p=s.get("progressivelyUpdatingReplicas", "none")
else:
    p=s["progressivelyUpdatingReplicas"][0]
print("rev" + str(p) + " template hash=" + str(d["metadata"]["annotations"].get("deployment.kubernetes.io/pod-template-hash", "none")) + "\n")
' 2>/dev/null"}

